<?php
namespace App\Filament\Resources;
use App\Filament\Resources\VoiceEventResource\Pages; use App\Models\VoiceEvent; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class VoiceEventResource extends Resource { protected static ?string $model=VoiceEvent::class; protected static ?string $navigationIcon='heroicon-o-signal'; protected static ?string $navigationLabel='Activité vocale'; protected static ?string $navigationGroup='Modération'; protected static ?int $navigationSort=20;
 public static function form(Form $form): Form{return $form->schema([Forms\Components\Section::make('Événement')->columns(2)->schema([Forms\Components\TextInput::make('type')->disabled(),Forms\Components\TextInput::make('discord_user_id')->disabled(),Forms\Components\Select::make('discord_guild_id')->label('Serveur')->relationship('guild','name')->disabled(),Forms\Components\Select::make('discord_channel_id')->label('Salon')->relationship('channel','name')->disabled(),Forms\Components\DateTimePicker::make('occurred_at')->disabled(),Forms\Components\KeyValue::make('payload')->columnSpanFull()->disabled()])]);}
 public static function table(Table $table): Table{return $table->modifyQueryUsing(fn(Builder $query)=>$query->where('occurred_at','>=',now()->subDay())->latest('occurred_at'))->poll('5s')->columns([Tables\Columns\TextColumn::make('occurred_at')->label('Date')->dateTime()->sortable(),Tables\Columns\TextColumn::make('type')->label('Événement')->formatStateUsing(fn(string $state):string=>match($state){'voice_join'=>'Arrivée','voice_leave'=>'Départ','voice_move'=>'Changement de salon','voice_mute'=>'Micro coupé','voice_unmute'=>'Micro réactivé','voice_deafen'=>'Sourdine activée','voice_undeafen'=>'Sourdine désactivée','screen_share_start'=>'Partage d’écran démarré','screen_share_stop'=>'Partage d’écran arrêté','bot_join'=>'Bot connecté','bot_leave'=>'Bot déconnecté',default=>$state})->badge()->color(fn(string $state):string=>match($state){'voice_join','voice_unmute','screen_share_start','bot_join'=>'success','voice_leave','voice_mute','screen_share_stop','bot_leave'=>'gray','voice_move'=>'warning','voice_deafen','voice_undeafen'=>'info',default=>'gray'})->sortable(),Tables\Columns\TextColumn::make('guild.name')->label('Serveur')->searchable(),Tables\Columns\TextColumn::make('channel.name')->label('Salon vocal')->searchable(),Tables\Columns\TextColumn::make('payload.display_name')->label('Utilisateur')->default(fn(VoiceEvent $record):string=>$record->discord_user_id ?: 'Système')->searchable(),Tables\Columns\TextColumn::make('discord_user_id')->label('ID utilisateur')->copyable()->toggleable(isToggledHiddenByDefault:true),Tables\Columns\TextColumn::make('payload.member_count')->label('Membres')->numeric()->placeholder('-')->toggleable(),Tables\Columns\TextColumn::make('payload.reason')->label('Détail')->limit(48)->placeholder('-')->toggleable(isToggledHiddenByDefault:true)])->filters([Tables\Filters\SelectFilter::make('type')->label('Événement')->options(['voice_join'=>'Arrivée','voice_leave'=>'Départ','voice_move'=>'Changement de salon','voice_mute'=>'Micro coupé','voice_unmute'=>'Micro réactivé','voice_deafen'=>'Sourdine activée','voice_undeafen'=>'Sourdine désactivée','screen_share_start'=>'Partage d’écran démarré','screen_share_stop'=>'Partage d’écran arrêté','bot_join'=>'Bot connecté','bot_leave'=>'Bot déconnecté'])])->actions([Tables\Actions\EditAction::make()->label('Voir')]);}
 public static function canCreate(): bool{return false;}
 public static function getPages():array{return ['index'=>Pages\ListVoiceEvents::route('/'),'edit'=>Pages\EditVoiceEvent::route('/{record}/edit')];}}
